// Package trust decides whether an image's content is the one its publisher
// released (§3.82): which identity must have signed it, what a verifier found,
// and whether that blocks, warns or passes.
//
// It holds the policy and the decision, not the tool. The verification itself
// is a Verifier — cosign, run by internal/scan — so this package imports
// nothing of DevDesk's own and every consumer (the remediation tab, the pull,
// the scan) reads the same table.
package trust

import (
	"crypto/sha256"
	"encoding/hex"
	"strings"
)

// Source is who declared a rule. It decides how hard a verdict lands: a rule
// the user wrote asks for a guarantee, a built-in one is DevDesk's guess on
// their behalf, and continuity is no declaration at all.
type Source int

const (
	// SourceContinuity is A: no rule, the identity that signed the image in use.
	SourceContinuity Source = iota
	// SourceBuiltin is B: a publisher DevDesk knows, measured before entering.
	SourceBuiltin
	// SourceUser is C: a rule of ~/.devdesk/trust.yaml.
	SourceUser
)

func (s Source) String() string {
	switch s {
	case SourceBuiltin:
		return "built-in"
	case SourceUser:
		return "user"
	}
	return "continuity"
}

// Mode is how a rule expects the image to be signed. It also names the tool:
// key and keyless are cosign's notions, and a notation block — refused for
// now — would be another verifier's.
type Mode int

const (
	// ModeKeyless is a Sigstore certificate: an OIDC issuer and a subject.
	ModeKeyless Mode = iota + 1
	// ModeKey is a public key the signature must verify against.
	ModeKey
	// ModeNone is `expect: none`: no signature is expected, and none is asked.
	ModeNone
)

// Identity is who a keyless certificate names.
type Identity struct {
	Issuer  string
	Subject string
}

// Key is one public key a key-mode rule accepts.
type Key struct {
	// Ref is where the key came from, for a person: a path, a KMS URI, or the
	// name of an embedded key.
	Ref string
	// PEM is the key itself. Empty for a KMS URI, which cosign resolves.
	PEM []byte
}

// KMS reports a key cosign fetches itself (awskms://, gcpkms://, …).
func (k Key) KMS() bool { return len(k.PEM) == 0 && strings.Contains(k.Ref, "://") }

// Rule is one declaration: images whose repository matches are signed this way.
type Rule struct {
	// Match is a glob on the normalized repository, without tag or digest:
	// `gcr.io/distroless/*`. A trailing `/**` matches any depth below.
	Match string
	Mode  Mode

	// Keys are accepted in key mode: the signature verifies if one of them
	// does. More than one only while a publisher rotates.
	Keys []Key
	// TLog asks for a transparency-log entry, in key mode. On by default: a
	// signature nobody logged is refused unless the rule says otherwise.
	TLog bool

	// Issuer, and one of Subject or SubjectRegexp, in keyless mode.
	Issuer        string
	Subject       string
	SubjectRegexp string

	Source Source
	// Origin is what a refusal names so the reader knows what to change:
	// "~/.devdesk/trust.yaml:12", "built-in: distroless".
	Origin string
}

// Fingerprint identifies what a rule asks, and nothing else: a cached verdict
// is keyed by it, so editing the identity or the key invalidates the entry,
// while moving the rule or renaming its file does not.
func (r Rule) Fingerprint() string {
	h := sha256.New()
	write := func(parts ...string) {
		for _, p := range parts {
			h.Write([]byte(p))
			h.Write([]byte{0})
		}
	}
	switch r.Mode {
	case ModeKey:
		write("key", boolString(r.TLog))
		for _, k := range r.Keys {
			if k.KMS() {
				write("kms", k.Ref)
			} else {
				write("pem", string(k.PEM))
			}
		}
	case ModeKeyless:
		write("keyless", r.Issuer, r.Subject, r.SubjectRegexp)
	default:
		write("none")
	}
	return hex.EncodeToString(h.Sum(nil))
}

func boolString(b bool) string {
	if b {
		return "1"
	}
	return "0"
}

package trust

import (
	"path"
	"strings"
)

// Repository normalizes an image reference to the repository a rule matches:
// the registry host, then the path, without tag or digest. Docker Hub is
// spelled out — `python` is `docker.io/library/python` — so that
// `python:3.12` and `docker.io/library/python:3.12` fall under the same rule.
//
// It reads a reference the way remediation.ParseRef does, and a test holds the
// two in step: this package cannot import remediation, which imports scan,
// which implements this package's Verifier.
func Repository(ref string) string {
	s := strings.TrimSpace(ref)
	if before, _, ok := strings.Cut(s, "@"); ok {
		s = before
	}
	// A colon after the last slash is a tag; one before it is a registry port.
	if i := strings.LastIndex(s, ":"); i > strings.LastIndex(s, "/") {
		s = s[:i]
	}
	host, rest := "", s
	if first, after, ok := strings.Cut(s, "/"); ok &&
		(strings.ContainsAny(first, ".:") || first == "localhost") {
		host, rest = first, after
	}
	if host == "" || host == "docker.io" || host == "index.docker.io" {
		host = "docker.io"
		rest = strings.TrimPrefix(rest, "docker.io/")
		if !strings.Contains(rest, "/") {
			rest = "library/" + rest
		}
	}
	return host + "/" + rest
}

// Digest is the digest a reference is pinned by, "" when there is none.
func Digest(ref string) string {
	if _, digest, ok := strings.Cut(ref, "@"); ok {
		return digest
	}
	return ""
}

// matches reports whether a rule's pattern covers a normalized repository.
// `*` stays within one path segment, as in path.Match; a pattern ending in
// `/**` covers everything below its prefix, at any depth.
func matches(pattern, repo string) bool {
	if prefix, ok := strings.CutSuffix(pattern, "/**"); ok {
		return strings.HasPrefix(repo, prefix+"/")
	}
	ok, err := path.Match(pattern, repo)
	return err == nil && ok
}

// validPattern refuses what path.Match cannot read, and a `**` anywhere but at
// the end: in the middle of a pattern it would silently mean one segment.
func validPattern(pattern string) bool {
	body := strings.TrimSuffix(pattern, "/**")
	if strings.Contains(body, "**") {
		return false
	}
	_, err := path.Match(body, "")
	return err == nil
}

// shadows reports a rule no image can reach because an earlier one already
// matches everything it would. Only the certain cases are reported — the same
// pattern, or a literal one the earlier pattern covers — so the warning is
// never wrong, only sometimes absent.
func shadows(earlier, later string) bool {
	if earlier == later {
		return true
	}
	if strings.ContainsAny(later, "*?[") {
		return false
	}
	return matches(earlier, later)
}

// Lookup finds the rule for a reference: the user's rules first, in file order,
// then the built-in ones. The first that matches wins.
func (p Policy) Lookup(ref string) (Rule, bool) {
	repo := Repository(ref)
	for _, rules := range [][]Rule{p.Rules, Builtin()} {
		for _, r := range rules {
			if matches(r.Match, repo) {
				return r, true
			}
		}
	}
	return Rule{}, false
}

package trust

import (
	_ "embed"
	"slices"
)

// dhiKey is Docker Hardened Images' signing key, dhi-2 — the only one the
// keyring marks active. It is compiled in, never fetched: fetching it would
// rest the trust on a network answer that could carry an attacker's key along
// with their image (§3.82).
//
// Cross-checked on 2026-09-25 from three sources that agree —
// registry.scout.docker.com/keyring/dhi/latest.pub, dhi.io/keyring/2.pub, and
// github.com/docker-hardened-images/keyring publickey/dhi-2.pub — SHA-256 of
// the DER form 118ba556dd52f4aec67018efd316c285c783cd3e54cc0f4527605715c643887c.
// dhi-1 is left out: inactive, with no reason given, and it verifies none of the
// images measured.
//
//go:embed keys/dhi-2.pub
var dhiKey []byte

// builtinRules is B: publishers DevDesk knows, each one entered only after a
// real `cosign verify` succeeded (§3.82). A publisher whose identity has not
// been measured does not enter, even a well-known one.
var builtinRules = []Rule{
	// Measured 2026-09-25 on gcr.io/distroless/static-debian12:nonroot.
	{
		Match: "gcr.io/distroless/**", Mode: ModeKeyless,
		Issuer:  "https://accounts.google.com",
		Subject: "keyless@distroless.iam.gserviceaccount.com",
		Source:  SourceBuiltin, Origin: "built-in: distroless",
	},
	// Measured 2026-09-25 on cgr.dev/chainguard/{static,python,node,wolfi-base}:
	// the same identity on all four.
	{
		Match: "cgr.dev/chainguard/**", Mode: ModeKeyless,
		Issuer:  "https://token.actions.githubusercontent.com",
		Subject: "https://github.com/chainguard-images/images/.github/workflows/release.yaml@refs/heads/main",
		Source:  SourceBuiltin, Origin: "built-in: Chainguard",
	},
	// Measured 2026-09-25 on dhi.io/static:20250419. Key mode, with the
	// signature in the OCI referrers — hence --experimental-oci11, always.
	{
		Match: "dhi.io/**", Mode: ModeKey, TLog: true,
		Keys:   []Key{{Ref: "embedded: dhi-2", PEM: dhiKey}},
		Source: SourceBuiltin, Origin: "built-in: Docker Hardened Images",
	},
}

// Builtin returns the built-in rules, in the order they are looked up.
func Builtin() []Rule { return slices.Clone(builtinRules) }

package trust

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

// PolicyVersion is the only `version:` a policy file may declare.
const PolicyVersion = 1

// Policy is C: the rules of ~/.devdesk/trust.yaml, in file order.
type Policy struct {
	Rules []Rule
}

// fileRule is one rule as it is written. Exactly one of Key, Keyless, Expect
// and Notation may be set: the mode names the tool, so there is no `tool:`
// field that could contradict it.
type fileRule struct {
	Match    string       `yaml:"match"`
	Key      string       `yaml:"key"`
	TLog     *bool        `yaml:"tlog"`
	Keyless  *fileKeyless `yaml:"keyless"`
	Expect   string       `yaml:"expect"`
	Notation *yaml.Node   `yaml:"notation"`
}

type fileKeyless struct {
	Issuer        string `yaml:"issuer"`
	Subject       string `yaml:"subject"`
	SubjectRegexp string `yaml:"subject_regexp"`
}

type policyFile struct {
	Version int        `yaml:"version"`
	Rules   []fileRule `yaml:"rules"`
}

// PolicyPath is where the user's rules live. It is global, not a context's:
// which identity to trust is a fact about the world, not a setting of one
// target (§3.82) — and ~/.devdesk/config.yaml is the default context, not a
// global file.
func PolicyPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".devdesk", "trust.yaml"), nil
}

// Load reads a policy file. A file that does not exist is an empty policy.
//
// It is strict where config.Load is not: an unknown key is an error, and an
// error rejects the whole file. A typo such as `isuer:` would otherwise drop
// the issuer from a rule without a word, and a rule weakened in silence is
// worse than no rule. The warnings are rules no image can reach.
func Load(path string) (Policy, []string, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return Policy{}, nil, nil
	}
	if err != nil {
		return Policy{}, nil, err
	}
	return parsePolicy(path, data)
}

func parsePolicy(path string, data []byte) (Policy, []string, error) {
	var file policyFile
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	if err := dec.Decode(&file); err != nil {
		if errors.Is(err, errEmptyDocument(err)) {
			return Policy{}, nil, fmt.Errorf("%s: version is required", path)
		}
		return Policy{}, nil, fmt.Errorf("%s: %w", path, err)
	}
	if file.Version != PolicyVersion {
		return Policy{}, nil, fmt.Errorf("%s: version must be %d, got %d", path, PolicyVersion, file.Version)
	}

	lines := ruleLines(data)
	dir := filepath.Dir(path)
	var policy Policy
	var warnings []string
	for i, fr := range file.Rules {
		origin := fmt.Sprintf("%s:%d", path, lineOf(lines, i))
		rule, err := fr.rule(origin, dir)
		if err != nil {
			return Policy{}, nil, fmt.Errorf("%s: %w", origin, err)
		}
		for _, prev := range policy.Rules {
			if shadows(prev.Match, rule.Match) {
				warnings = append(warnings, fmt.Sprintf("%s: never used, %s already matches %s", origin, prev.Origin, rule.Match))
				break
			}
		}
		policy.Rules = append(policy.Rules, rule)
	}
	return policy, warnings, nil
}

// errEmptyDocument maps yaml's end-of-input on an empty file to itself, so an
// empty file reads as a missing version rather than as a parse error.
func errEmptyDocument(err error) error {
	if err.Error() == "EOF" {
		return err
	}
	return errNever
}

var errNever = errors.New("never")

// ruleLines is the line of each rule, for the origin a refusal names. The
// strict decode above cannot give it; a second, lenient pass over the node tree
// can.
func ruleLines(data []byte) []int {
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil || len(doc.Content) == 0 {
		return nil
	}
	root := doc.Content[0]
	for i := 0; i+1 < len(root.Content); i += 2 {
		if root.Content[i].Value != "rules" {
			continue
		}
		var out []int
		for _, item := range root.Content[i+1].Content {
			out = append(out, item.Line)
		}
		return out
	}
	return nil
}

func lineOf(lines []int, i int) int {
	if i < len(lines) {
		return lines[i]
	}
	return 0
}

func (fr fileRule) rule(origin, dir string) (Rule, error) {
	if fr.Match == "" {
		return Rule{}, errors.New("match is required")
	}
	if !validPattern(fr.Match) {
		return Rule{}, fmt.Errorf("match %q is not a valid pattern (`*` is one path segment, `/**` only at the end)", fr.Match)
	}
	modes := 0
	for _, set := range []bool{fr.Key != "", fr.Keyless != nil, fr.Expect != "", fr.Notation != nil} {
		if set {
			modes++
		}
	}
	if modes != 1 {
		return Rule{}, errors.New("a rule declares exactly one of key, keyless, expect")
	}
	if fr.TLog != nil && fr.Key == "" {
		return Rule{}, errors.New("tlog applies to key rules only")
	}

	rule := Rule{Match: fr.Match, Source: SourceUser, Origin: origin}
	switch {
	case fr.Notation != nil:
		return Rule{}, errors.New("notation is not supported yet")
	case fr.Expect != "":
		if fr.Expect != "none" {
			return Rule{}, fmt.Errorf("expect must be none, got %q", fr.Expect)
		}
		rule.Mode = ModeNone
	case fr.Keyless != nil:
		k := *fr.Keyless
		if k.Issuer == "" {
			return Rule{}, errors.New("keyless needs an issuer")
		}
		if (k.Subject == "") == (k.SubjectRegexp == "") {
			return Rule{}, errors.New("keyless needs exactly one of subject, subject_regexp")
		}
		if k.SubjectRegexp != "" {
			if _, err := regexp.Compile(k.SubjectRegexp); err != nil {
				return Rule{}, fmt.Errorf("subject_regexp: %w", err)
			}
		}
		rule.Mode, rule.Issuer, rule.Subject, rule.SubjectRegexp = ModeKeyless, k.Issuer, k.Subject, k.SubjectRegexp
	default:
		key, err := readKey(fr.Key, dir)
		if err != nil {
			return Rule{}, err
		}
		rule.Mode, rule.Keys, rule.TLog = ModeKey, []Key{key}, fr.TLog == nil || *fr.TLog
	}
	return rule, nil
}

// readKey loads a key file when the policy is read, not when an image is
// verified: an unreadable key rejects the file at once, the way a typo does,
// and the key's content — not its path — is what the cache fingerprint covers.
// A KMS URI is left for cosign to resolve.
func readKey(ref, dir string) (Key, error) {
	if strings.Contains(ref, "://") {
		return Key{Ref: ref}, nil
	}
	path := ref
	if rest, ok := strings.CutPrefix(path, "~/"); ok {
		home, err := os.UserHomeDir()
		if err != nil {
			return Key{}, err
		}
		path = filepath.Join(home, rest)
	} else if !filepath.IsAbs(path) {
		path = filepath.Join(dir, path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Key{}, fmt.Errorf("key: %w", err)
	}
	if !bytes.Contains(data, []byte("PUBLIC KEY-----")) {
		return Key{}, fmt.Errorf("key %s is not a PEM public key", ref)
	}
	return Key{Ref: ref, PEM: data}, nil
}

