package trust

// Verdict is what a verification found about one image.
type Verdict int

const (
	// NoPolicy is the absence of a question: no rule, no signature on the image
	// in use to compare with, or `expect: none`. Not a no — nothing to say.
	NoPolicy Verdict = iota
	// Verified is the expected identity or key having signed this digest.
	Verified
	// IdentityMismatch is a valid signature by someone else — the one verdict
	// that says the content was replaced, whoever declared the rule.
	IdentityMismatch
	// Unsigned is no signature — or, in key mode, none the expected key
	// verifies. Under a rule it is what a republished tag looks like: its new
	// digest carries none of the old signatures.
	Unsigned
	// Failed is a question that could not be asked: registry, blob store or
	// Sigstore unreachable, cosign missing, a timeout.
	Failed
)

func (v Verdict) String() string {
	switch v {
	case Verified:
		return "verified"
	case IdentityMismatch:
		return "identity-mismatch"
	case Unsigned:
		return "unsigned"
	case Failed:
		return "failed"
	}
	return "no-policy"
}

// parseVerdict reads String back, for the cache. Anything else is NoPolicy,
// which is never stored: an unreadable entry is a miss.
func parseVerdict(s string) Verdict {
	for _, v := range []Verdict{Verified, IdentityMismatch, Unsigned, Failed} {
		if v.String() == s {
			return v
		}
	}
	return NoPolicy
}

// Decision is what a verdict does to the action asking for it.
type Decision int

const (
	// Allow lets the pull or the choice go ahead.
	Allow Decision = iota
	// Warn lets it go ahead, and says why it might not have.
	Warn
	// Block refuses it, naming the rule.
	Block
)

// Decide is §3.82's table, and the only copy of it: the pull, the remediation
// tab and the scan finding all read it.
//
//	verdict            user (C)  built-in (B)  continuity (A)
//	IdentityMismatch   block     block         block
//	Unsigned           block     block         warn
//	Failed             block     warn          warn
//
// A rule someone wrote asks for a guarantee, so not knowing blocks there. A
// built-in rule is DevDesk's declaration, not the user's: a proxy that filters
// Sigstore must not stop every Chainguard pull of someone who configured
// nothing. Continuity declares nothing at all, and a publisher may stop signing.
//
// Key mode never reaches Failed through an exit code — the verifier classes it
// Unsigned, fail-closed (§3.82) — so a built-in key rule blocks where a keyless
// one would warn. That is the one deliberate exception to the table, and it
// lives in the verifier, not here.
func Decide(v Verdict, s Source) Decision {
	switch v {
	case IdentityMismatch:
		return Block
	case Unsigned:
		if s == SourceContinuity {
			return Warn
		}
		return Block
	case Failed:
		if s == SourceUser {
			return Block
		}
		return Warn
	}
	return Allow
}

package trust

import (
	"context"
	"errors"
	"fmt"
)

// Verifier checks a signature. The production one is cosign, run by
// internal/scan; tests give a table.
type Verifier interface {
	// Verify asks whether ref — pinned by digest — is signed the way rule says.
	// The error explains a Failed verdict, for the log; the verdict is the
	// answer.
	Verify(ctx context.Context, ref string, rule Rule) (Verdict, error)
	// Identities returns who the signatures on ref *claim* to be. They are
	// hints and nothing more: a claim is only believed once Verify has proven
	// it (see Continuity).
	Identities(ctx context.Context, ref string) ([]Identity, error)
}

// Result is one image's answer, with what a person needs to act on it.
type Result struct {
	Verdict  Verdict
	Decision Decision
	// Rule is what the verdict was measured against; for continuity, a rule
	// built from the identity of the image in use.
	Rule Rule
	// Err explains a Failed verdict, for the log.
	Err error
}

// ErrNotPinned is a reference with no digest. A tag is only a name: verifying
// it and then using it lets the tag move in between, which is the attack.
var ErrNotPinned = errors.New("reference is not pinned by digest")

// Evaluate answers for candidate, pinned by digest. current is the image in
// use — also pinned — for continuity, "" when there is none.
//
// The rule comes from the policy, then the built-in list; with no rule, the
// candidate must be signed by whoever signed current.
func Evaluate(ctx context.Context, p Policy, v Verifier, candidate, current string) Result {
	if Digest(candidate) == "" {
		return Result{Verdict: Failed, Decision: Decide(Failed, SourceContinuity), Err: ErrNotPinned}
	}
	if rule, ok := p.Lookup(candidate); ok {
		if rule.Mode == ModeNone {
			return Result{Verdict: NoPolicy, Decision: Allow, Rule: rule}
		}
		verdict, err := v.Verify(ctx, candidate, rule)
		return Result{Verdict: verdict, Decision: Decide(verdict, rule.Source), Rule: rule, Err: err}
	}
	if current == "" || Digest(current) == "" {
		return Result{Verdict: NoPolicy, Decision: Allow}
	}
	verdict, rule, err := Continuity(ctx, v, candidate, current)
	return Result{Verdict: verdict, Decision: Decide(verdict, SourceContinuity), Rule: rule, Err: err}
}

// Continuity is A: the candidate must be signed by the identity that signed
// the image in use.
//
// The identity is never read and believed. A permissive check passes as soon
// as *one* signature is valid, so an attacker could attach their own valid
// signature next to a bundle whose forged certificate names the expected
// identity; reading the certificate would then report Verified. So each
// claimed identity is first verified strictly on the image in use, and only an
// identity cosign has proven there is asked of the candidate.
func Continuity(ctx context.Context, v Verifier, candidate, current string) (Verdict, Rule, error) {
	claims, err := v.Identities(ctx, current)
	if err != nil {
		return Failed, Rule{}, fmt.Errorf("identities of %s: %w", current, err)
	}
	for _, id := range claims {
		rule := Rule{
			Mode: ModeKeyless, Issuer: id.Issuer, Subject: id.Subject,
			Source: SourceContinuity, Origin: "continuity with " + current,
		}
		proven, err := v.Verify(ctx, current, rule)
		if err != nil || proven != Verified {
			continue
		}
		verdict, err := v.Verify(ctx, candidate, rule)
		return verdict, rule, err
	}
	// Nothing on the image in use that could be proven: nothing to continue.
	return NoPolicy, Rule{}, nil
}

// Reason is the sentence a refusal or a warning shows, naming the rule so the
// reader knows what to change. Empty when there is nothing to say.
func (r Result) Reason() string {
	var what string
	switch r.Verdict {
	case IdentityMismatch:
		what = "Signed by an unexpected identity"
	case Unsigned:
		what = "Not signed"
		if r.Rule.Mode == ModeKey {
			what = "No verifiable signature from the expected key"
		}
	case Failed:
		what = "Signature could not be verified"
	default:
		return ""
	}
	if r.Rule.Origin == "" {
		return what
	}
	return what + " — " + r.Rule.Origin
}

package trust

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// How long a verdict is reused. A digest never changes, but a signature can be
// added to it later, and keys and logs move: Unsigned is asked again sooner.
// Failed is never stored — a block under a user rule would outlast the network
// coming back.
const (
	verifiedTTL = 24 * time.Hour
	unsignedTTL = 6 * time.Hour
)

func ttl(v Verdict) (time.Duration, bool) {
	switch v {
	case Verified, IdentityMismatch:
		return verifiedTTL, true
	case Unsigned:
		return unsignedTTL, true
	}
	return 0, false
}

// Store keeps verdicts between runs.
type Store interface {
	Get(key string) (Verdict, time.Time, bool)
	Set(key string, v Verdict, at time.Time) error
}

// Cached wraps a verifier so a digest already answered under the same rule is
// not asked again. The key is the digest and the rule's fingerprint: editing
// the rule is a miss. Identities are not cached — they are hints, and cheap
// next to the strict checks they lead to, which are.
func Cached(v Verifier, s Store, now func() time.Time) Verifier {
	return cached{inner: v, store: s, now: now}
}

type cached struct {
	inner Verifier
	store Store
	now   func() time.Time
}

func (c cached) Verify(ctx context.Context, ref string, rule Rule) (Verdict, error) {
	digest := Digest(ref)
	if digest == "" {
		return c.inner.Verify(ctx, ref, rule)
	}
	key := digest + " " + rule.Fingerprint()
	if v, at, ok := c.store.Get(key); ok {
		if d, keep := ttl(v); keep && c.now().Sub(at) < d {
			return v, nil
		}
	}
	v, err := c.inner.Verify(ctx, ref, rule)
	if _, keep := ttl(v); keep {
		// A verdict that could not be stored is still the answer.
		_ = c.store.Set(key, v, c.now())
	}
	return v, err
}

func (c cached) Identities(ctx context.Context, ref string) ([]Identity, error) {
	return c.inner.Identities(ctx, ref)
}

// FileStore is the Store on disk: ~/.devdesk/cache/signature-verdicts.json.
//
// It lives here rather than in internal/cache because that package imports
// internal/scan, which implements this package's Verifier.
type FileStore struct {
	// Path is the file; empty is the default location.
	Path string
}

type storeEntry struct {
	Verdict   string    `json:"verdict"`
	CheckedAt time.Time `json:"checked_at"`
}

type storeFile struct {
	Version int                   `json:"version"`
	Entries map[string]storeEntry `json:"entries"`
}

const storeVersion = 1

// storeMu serializes every read-modify-write: verifications run on several Cmds.
var storeMu sync.Mutex

func (s FileStore) path() (string, error) {
	if s.Path != "" {
		return s.Path, nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".devdesk", "cache", "signature-verdicts.json"), nil
}

// Get returns a stored verdict. A missing or unreadable file is a miss.
func (s FileStore) Get(key string) (Verdict, time.Time, bool) {
	path, err := s.path()
	if err != nil {
		return NoPolicy, time.Time{}, false
	}
	storeMu.Lock()
	defer storeMu.Unlock()
	entries, err := readStore(path)
	if err != nil {
		return NoPolicy, time.Time{}, false
	}
	e, ok := entries[key]
	if !ok {
		return NoPolicy, time.Time{}, false
	}
	v := parseVerdict(e.Verdict)
	return v, e.CheckedAt, v != NoPolicy
}

// Set stores one verdict, keeping the others.
func (s FileStore) Set(key string, v Verdict, at time.Time) error {
	path, err := s.path()
	if err != nil {
		return err
	}
	storeMu.Lock()
	defer storeMu.Unlock()
	entries, err := readStore(path)
	if err != nil {
		// A corrupt file is replaced rather than blocking every later write.
		entries = map[string]storeEntry{}
	}
	entries[key] = storeEntry{Verdict: v.String(), CheckedAt: at}
	data, err := json.MarshalIndent(storeFile{Version: storeVersion, Entries: entries}, "", "  ")
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o600); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

func readStore(path string) (map[string]storeEntry, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]storeEntry{}, nil
	}
	if err != nil {
		return nil, err
	}
	var file storeFile
	if err := json.Unmarshal(data, &file); err != nil {
		return nil, fmt.Errorf("decode %s: %w", path, err)
	}
	if file.Entries == nil {
		file.Entries = map[string]storeEntry{}
	}
	return file.Entries, nil
}

