package trust

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const testKey = `-----BEGIN PUBLIC KEY-----
REDACTED
REDACTED
-----END PUBLIC KEY-----
`

// writePolicy writes a trust.yaml, and a key beside it, in a fresh directory.
func writePolicy(t *testing.T, body string) string {
	t.Helper()
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "corp.pub"), []byte(testKey), 0o600); err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(dir, "trust.yaml")
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatal(err)
	}
	return path
}

func mustLoad(t *testing.T, body string) (Policy, []string) {
	t.Helper()
	p, warnings, err := Load(writePolicy(t, body))
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	return p, warnings
}

func loadErr(t *testing.T, body string) error {
	t.Helper()
	p, _, err := Load(writePolicy(t, body))
	if err == nil {
		t.Fatalf("Load accepted the file: %+v", p)
	}
	if len(p.Rules) != 0 {
		t.Errorf("a rejected file still yielded %d rules — the whole file must go", len(p.Rules))
	}
	return err
}

func TestLoadReadsEveryMode(t *testing.T) {
	p, warnings := mustLoad(t, `version: 1
rules:
  - match: registry.corp.example/base/*
    key: corp.pub
    tlog: false
  - match: cgr.dev/chainguard/**
    keyless:
      issuer: https://token.actions.githubusercontent.com
      subject: https://github.com/chainguard-images/images/.github/workflows/release.yaml@refs/heads/main
  - match: ghcr.io/acme/*
    keyless:
      issuer: https://token.actions.githubusercontent.com
      subject_regexp: ^https://github.com/acme/
  - match: registry.corp.example/legacy/*
    expect: none
  - match: registry.corp.example/signed/*
    key: corp.pub
`)
	if len(warnings) != 0 {
		t.Errorf("warnings = %v, want none", warnings)
	}
	if len(p.Rules) != 5 {
		t.Fatalf("got %d rules, want 5", len(p.Rules))
	}
	key, keyless, re, none, tlogDefault := p.Rules[0], p.Rules[1], p.Rules[2], p.Rules[3], p.Rules[4]

	if key.Mode != ModeKey || key.TLog || len(key.Keys) != 1 || string(key.Keys[0].PEM) != testKey {
		t.Errorf("key rule = %+v", key)
	}
	if keyless.Mode != ModeKeyless || keyless.Issuer == "" || keyless.Subject == "" {
		t.Errorf("keyless rule = %+v", keyless)
	}
	if re.SubjectRegexp != "^https://github.com/acme/" || re.Subject != "" {
		t.Errorf("regexp rule = %+v", re)
	}
	if none.Mode != ModeNone {
		t.Errorf("expect: none gave mode %v", none.Mode)
	}
	if !tlogDefault.TLog {
		t.Error("a key rule that says nothing about tlog must require it")
	}
	for _, r := range p.Rules {
		if r.Source != SourceUser {
			t.Errorf("%s: source %v, want user", r.Match, r.Source)
		}
	}
	// The origin a refusal names is the file and the rule's own line.
	if !strings.HasSuffix(key.Origin, "trust.yaml:3") || !strings.HasSuffix(keyless.Origin, "trust.yaml:6") {
		t.Errorf("origins = %q, %q", key.Origin, keyless.Origin)
	}
}

// The reason the file is strict: a typo must not weaken a rule in silence.
func TestAnUnknownKeyRejectsTheWholeFile(t *testing.T) {
	err := loadErr(t, `version: 1
rules:
  - match: registry.corp.example/other/*
    expect: none
  - match: cgr.dev/chainguard/**
    keyless:
      isuer: https://token.actions.githubusercontent.com
      subject: x
`)
	if !strings.Contains(err.Error(), "isuer") {
		t.Errorf("error %q does not name the unknown key", err)
	}
}

func TestARuleDeclaresExactlyOneMode(t *testing.T) {
	loadErr(t, "version: 1\nrules:\n  - match: a.io/*\n    key: corp.pub\n    expect: none\n")
	loadErr(t, "version: 1\nrules:\n  - match: a.io/*\n")
}

func TestTheVersionIsRequired(t *testing.T) {
	loadErr(t, "rules: []\n")
	loadErr(t, "")
	err := loadErr(t, "version: 2\nrules: []\n")
	if !strings.Contains(err.Error(), "version must be 1") {
		t.Errorf("error = %q", err)
	}
}

func TestNotationIsReservedAndRefused(t *testing.T) {
	err := loadErr(t, "version: 1\nrules:\n  - match: a.io/*\n    notation:\n      trust_store: ca:corp\n")
	if !strings.Contains(err.Error(), "not supported yet") {
		t.Errorf("error = %q", err)
	}
}

func TestInvalidRulesAreRefused(t *testing.T) {
	for name, body := range map[string]string{
		"tlog on keyless":       "  - match: a.io/*\n    tlog: false\n    keyless: {issuer: i, subject: s}\n",
		"no issuer":             "  - match: a.io/*\n    keyless: {subject: s}\n",
		"subject and regexp":    "  - match: a.io/*\n    keyless: {issuer: i, subject: s, subject_regexp: r}\n",
		"bad regexp":            "  - match: a.io/*\n    keyless: {issuer: i, subject_regexp: '('}\n",
		"expect something else": "  - match: a.io/*\n    expect: signed\n",
		"no match":              "  - expect: none\n",
		"double star inside":    "  - match: a.io/**/x\n    expect: none\n",
		"missing key file":      "  - match: a.io/*\n    key: nope.pub\n",
	} {
		t.Run(name, func(t *testing.T) { loadErr(t, "version: 1\nrules:\n"+body) })
	}
}

func TestAKeyThatIsNotAPublicKeyIsRefused(t *testing.T) {
	path := writePolicy(t, "version: 1\nrules:\n  - match: a.io/*\n    key: junk.pub\n")
	if err := os.WriteFile(filepath.Join(filepath.Dir(path), "junk.pub"), []byte("hello"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, _, err := Load(path); err == nil {
		t.Fatal("a key file that is not a PEM public key was accepted")
	}
}

func TestAKMSKeyIsLeftToCosign(t *testing.T) {
	p, _ := mustLoad(t, "version: 1\nrules:\n  - match: a.io/*\n    key: awskms:///alias/cosign\n")
	k := p.Rules[0].Keys[0]
	if !k.KMS() || k.Ref != "awskms:///alias/cosign" {
		t.Errorf("key = %+v", k)
	}
}

func TestAMissingFileIsAnEmptyPolicy(t *testing.T) {
	p, warnings, err := Load(filepath.Join(t.TempDir(), "trust.yaml"))
	if err != nil || len(p.Rules) != 0 || len(warnings) != 0 {
		t.Errorf("Load(missing) = %+v, %v, %v", p, warnings, err)
	}
}

func TestARuleNoImageCanReachIsWarned(t *testing.T) {
	_, warnings := mustLoad(t, `version: 1
rules:
  - match: registry.corp.example/*
    expect: none
  - match: registry.corp.example/app
    expect: none
  - match: registry.corp.example/b*
    expect: none
`)
	// The literal one is certainly shadowed; the pattern one is not reported,
	// since the check only speaks when it is sure.
	if len(warnings) != 1 || !strings.Contains(warnings[0], "registry.corp.example/app") {
		t.Errorf("warnings = %v", warnings)
	}
}

package trust

import "testing"

func TestRepositoryNormalizesTheWayARuleIsMatched(t *testing.T) {
	for ref, want := range map[string]string{
		"python":                                   "docker.io/library/python",
		"python:3.12":                              "docker.io/library/python",
		"docker.io/library/python:3.12":            "docker.io/library/python",
		"index.docker.io/bitnami/redis:7":          "docker.io/bitnami/redis",
		"bitnami/redis@sha256:abc":                 "docker.io/bitnami/redis",
		"gcr.io/distroless/static-debian12:nonroot": "gcr.io/distroless/static-debian12",
		"localhost:5000/demo:1":                    "localhost:5000/demo",
		"registry.corp.example:8443/a/b/c:1@sha256:x": "registry.corp.example:8443/a/b/c",
	} {
		if got := Repository(ref); got != want {
			t.Errorf("Repository(%q) = %q, want %q", ref, got, want)
		}
	}
}

func TestMatchingKeepsStarToOneSegment(t *testing.T) {
	for _, c := range []struct {
		pattern, repo string
		want          bool
	}{
		{"gcr.io/distroless/*", "gcr.io/distroless/static", true},
		{"gcr.io/distroless/*", "gcr.io/distroless/a/b", false},
		{"gcr.io/distroless/**", "gcr.io/distroless/a/b", true},
		{"gcr.io/distroless/**", "gcr.io/distroless", false},
		{"gcr.io/distroless/**", "gcr.io/distrolessX/a", false},
		{"docker.io/library/python", "docker.io/library/python", true},
	} {
		if got := matches(c.pattern, c.repo); got != c.want {
			t.Errorf("matches(%q, %q) = %v, want %v", c.pattern, c.repo, got, c.want)
		}
	}
}

func TestLookupPutsTheUserFirstThenTheBuiltinList(t *testing.T) {
	user := Policy{Rules: []Rule{
		{Match: "dhi.io/**", Mode: ModeNone, Source: SourceUser, Origin: "first"},
		{Match: "dhi.io/**", Mode: ModeNone, Source: SourceUser, Origin: "second"},
	}}
	if r, ok := user.Lookup("dhi.io/static:20250419@sha256:x"); !ok || r.Origin != "first" {
		t.Errorf("a user rule on the same scope must win over the built-in one, and the first user rule over the next: %+v", r)
	}
	if r, ok := (Policy{}).Lookup("gcr.io/distroless/static-debian12:nonroot"); !ok || r.Source != SourceBuiltin {
		t.Errorf("distroless should fall to the built-in rule: %+v, %v", r, ok)
	}
	if _, ok := (Policy{}).Lookup("python:3.12"); ok {
		t.Error("an image no rule names must have no rule")
	}
}

package trust

import "testing"

// §3.82's table, cell by cell: the pull, the remediation tab and the scan all
// read Decide, so a cell changed here changes all three.
func TestDecideIsTheTableOfTheBacklog(t *testing.T) {
	for _, c := range []struct {
		verdict Verdict
		source  Source
		want    Decision
	}{
		{IdentityMismatch, SourceUser, Block},
		{IdentityMismatch, SourceBuiltin, Block},
		{IdentityMismatch, SourceContinuity, Block},
		{Unsigned, SourceUser, Block},
		{Unsigned, SourceBuiltin, Block},
		{Unsigned, SourceContinuity, Warn},
		{Failed, SourceUser, Block},
		{Failed, SourceBuiltin, Warn},
		{Failed, SourceContinuity, Warn},
		{Verified, SourceUser, Allow},
		{Verified, SourceBuiltin, Allow},
		{Verified, SourceContinuity, Allow},
		{NoPolicy, SourceUser, Allow},
		{NoPolicy, SourceContinuity, Allow},
	} {
		if got := Decide(c.verdict, c.source); got != c.want {
			t.Errorf("Decide(%v, %v) = %v, want %v", c.verdict, c.source, got, c.want)
		}
	}
}

func TestAVerdictReadsBackFromItsName(t *testing.T) {
	for _, v := range []Verdict{Verified, IdentityMismatch, Unsigned, Failed} {
		if got := parseVerdict(v.String()); got != v {
			t.Errorf("parseVerdict(%q) = %v", v.String(), got)
		}
	}
	if parseVerdict("garbage") != NoPolicy {
		t.Error("an unknown name must read as NoPolicy, which is never stored")
	}
}

package trust

import (
	"context"
	"errors"
	"strings"
	"testing"
)

// fakeVerifier answers from a table keyed by reference and identity subject
// (or "key" for key mode), and records every question.
type fakeVerifier struct {
	verdicts   map[string]Verdict
	identities map[string][]Identity
	identErr   error
	asked      []string
}

func (f *fakeVerifier) Verify(_ context.Context, ref string, rule Rule) (Verdict, error) {
	who := rule.Subject
	if rule.Mode == ModeKey {
		who = "key"
	}
	f.asked = append(f.asked, ref+" "+who)
	v, ok := f.verdicts[ref+" "+who]
	if !ok {
		return Unsigned, nil
	}
	return v, nil
}

func (f *fakeVerifier) Identities(_ context.Context, ref string) ([]Identity, error) {
	return f.identities[ref], f.identErr
}

const (
	current   = "registry.example/app@sha256:old"
	candidate = "registry.example/app@sha256:new"
)

func TestAnUnpinnedReferenceIsNeverVerified(t *testing.T) {
	f := &fakeVerifier{}
	r := Evaluate(context.Background(), Policy{}, f, "gcr.io/distroless/static:nonroot", "")
	if r.Verdict != Failed || !errors.Is(r.Err, ErrNotPinned) {
		t.Errorf("result = %+v", r)
	}
	if len(f.asked) != 0 {
		t.Errorf("a tag was verified: %v — it can move between the check and the pull", f.asked)
	}
}

func TestExpectNoneAsksNothing(t *testing.T) {
	f := &fakeVerifier{}
	p := Policy{Rules: []Rule{{Match: "registry.example/*", Mode: ModeNone, Source: SourceUser}}}
	r := Evaluate(context.Background(), p, f, candidate, current)
	if r.Verdict != NoPolicy || r.Decision != Allow || len(f.asked) != 0 {
		t.Errorf("result = %+v, asked %v", r, f.asked)
	}
}

func TestAUserRuleDecidesWithTheUserSource(t *testing.T) {
	f := &fakeVerifier{}
	p := Policy{Rules: []Rule{{Match: "registry.example/*", Mode: ModeKey, Source: SourceUser, Origin: "trust.yaml:3"}}}
	r := Evaluate(context.Background(), p, f, candidate, current)
	if r.Verdict != Unsigned || r.Decision != Block {
		t.Errorf("result = %+v", r)
	}
	if want := "No verifiable signature from the expected key — trust.yaml:3"; r.Reason() != want {
		t.Errorf("reason = %q, want %q", r.Reason(), want)
	}
	// A rule is looked up before continuity: the image in use is not asked.
	for _, q := range f.asked {
		if strings.HasPrefix(q, current) {
			t.Errorf("continuity ran under a rule: %v", f.asked)
		}
	}
}

func TestNoRuleAndNothingInUseIsNoPolicy(t *testing.T) {
	r := Evaluate(context.Background(), Policy{}, &fakeVerifier{}, candidate, "")
	if r.Verdict != NoPolicy || r.Decision != Allow {
		t.Errorf("result = %+v", r)
	}
}

// The attack continuity must not fall for: the image in use carries a bundle
// whose certificate names the expected identity but does not verify.
func TestContinuityNeverBelievesAClaimedIdentity(t *testing.T) {
	forged := Identity{Issuer: "https://token.actions.githubusercontent.com", Subject: "trusted-release"}
	f := &fakeVerifier{
		identities: map[string][]Identity{current: {forged}},
		verdicts: map[string]Verdict{
			current + " trusted-release":   IdentityMismatch, // the claim does not prove out
			candidate + " trusted-release": Verified,
		},
	}
	r := Evaluate(context.Background(), Policy{}, f, candidate, current)
	if r.Verdict != NoPolicy {
		t.Fatalf("verdict = %v: an unproven claim was used", r.Verdict)
	}
	for _, q := range f.asked {
		if strings.HasPrefix(q, candidate) {
			t.Errorf("the candidate was asked about an identity nobody proved: %v", f.asked)
		}
	}
}

func TestContinuityAsksTheCandidateForTheProvenIdentity(t *testing.T) {
	proven := Identity{Issuer: "https://accounts.google.com", Subject: "release@example"}
	f := &fakeVerifier{
		identities: map[string][]Identity{current: {{Issuer: "x", Subject: "claimed-only"}, proven}},
		verdicts: map[string]Verdict{
			current + " release@example": Verified,
		},
	}
	r := Evaluate(context.Background(), Policy{}, f, candidate, current)
	// The candidate is unsigned: under continuity that warns, it does not block.
	if r.Verdict != Unsigned || r.Decision != Warn || r.Rule.Source != SourceContinuity {
		t.Errorf("result = %+v", r)
	}
	if !strings.Contains(r.Reason(), "continuity with "+current) {
		t.Errorf("reason %q does not say what it continued", r.Reason())
	}
}

func TestContinuityThatCannotReadIdentitiesFails(t *testing.T) {
	f := &fakeVerifier{identErr: errors.New("registry unreachable")}
	r := Evaluate(context.Background(), Policy{}, f, candidate, current)
	if r.Verdict != Failed || r.Decision != Warn {
		t.Errorf("result = %+v", r)
	}
}

func TestAMismatchUnderContinuityBlocks(t *testing.T) {
	proven := Identity{Issuer: "i", Subject: "s"}
	f := &fakeVerifier{
		identities: map[string][]Identity{current: {proven}},
		verdicts: map[string]Verdict{
			current + " s":   Verified,
			candidate + " s": IdentityMismatch,
		},
	}
	if r := Evaluate(context.Background(), Policy{}, f, candidate, current); r.Decision != Block {
		t.Errorf("result = %+v", r)
	}
}

package trust

import (
	"crypto/sha256"
	"crypto/x509"
	"encoding/hex"
	"encoding/pem"
	"testing"
)

// dhiKeyFingerprint is the SHA-256 of dhi-2's DER form, cross-checked on
// 2026-09-25 against three sources (§3.82). Changing the embedded key without
// changing this is the mistake this test exists to stop.
const dhiKeyFingerprint = "REDACTED"

func TestTheEmbeddedDHIKeyIsTheCrossCheckedOne(t *testing.T) {
	block, _ := pem.Decode(dhiKey)
	if block == nil {
		t.Fatal("the embedded DHI key is not PEM")
	}
	if _, err := x509.ParsePKIXPublicKey(block.Bytes); err != nil {
		t.Fatalf("the embedded DHI key does not parse: %v", err)
	}
	sum := sha256.Sum256(block.Bytes)
	if got := hex.EncodeToString(sum[:]); got != dhiKeyFingerprint {
		t.Errorf("embedded DHI key fingerprint = %s, want %s", got, dhiKeyFingerprint)
	}
}

func TestEveryBuiltinRuleIsComplete(t *testing.T) {
	for _, r := range Builtin() {
		if r.Source != SourceBuiltin || r.Origin == "" || !validPattern(r.Match) {
			t.Errorf("%s: source %v, origin %q", r.Match, r.Source, r.Origin)
		}
		switch r.Mode {
		case ModeKeyless:
			if r.Issuer == "" || r.Subject == "" {
				t.Errorf("%s: keyless without a pinned identity", r.Match)
			}
		case ModeKey:
			if len(r.Keys) == 0 || !r.TLog {
				t.Errorf("%s: key rule without a key, or without the log", r.Match)
			}
		default:
			t.Errorf("%s: a built-in rule must expect a signature", r.Match)
		}
	}
}

package trust

import (
	"context"
	"path/filepath"
	"testing"
	"time"
)

type countingVerifier struct {
	verdict Verdict
	calls   int
}

func (c *countingVerifier) Verify(context.Context, string, Rule) (Verdict, error) {
	c.calls++
	return c.verdict, nil
}

func (c *countingVerifier) Identities(context.Context, string) ([]Identity, error) { return nil, nil }

func cachedAt(t *testing.T, v Verdict) (*countingVerifier, Verifier, *time.Time) {
	t.Helper()
	inner := &countingVerifier{verdict: v}
	now := time.Date(2026, 9, 25, 12, 0, 0, 0, time.UTC)
	store := FileStore{Path: filepath.Join(t.TempDir(), "signature-verdicts.json")}
	return inner, Cached(inner, store, func() time.Time { return now }), &now
}

var cacheRule = Rule{Mode: ModeKeyless, Issuer: "i", Subject: "s"}

func TestAVerifiedDigestIsNotAskedAgainForADay(t *testing.T) {
	inner, v, now := cachedAt(t, Verified)
	ctx := context.Background()
	_, _ = v.Verify(ctx, candidate, cacheRule)
	*now = now.Add(23 * time.Hour)
	if got, _ := v.Verify(ctx, candidate, cacheRule); got != Verified || inner.calls != 1 {
		t.Errorf("verdict %v after %d calls, want the stored one after 1", got, inner.calls)
	}
	*now = now.Add(2 * time.Hour)
	_, _ = v.Verify(ctx, candidate, cacheRule)
	if inner.calls != 2 {
		t.Errorf("calls = %d: a day-old verdict must be asked again", inner.calls)
	}
}

func TestUnsignedIsAskedAgainSooner(t *testing.T) {
	inner, v, now := cachedAt(t, Unsigned)
	ctx := context.Background()
	_, _ = v.Verify(ctx, candidate, cacheRule)
	*now = now.Add(7 * time.Hour)
	_, _ = v.Verify(ctx, candidate, cacheRule)
	if inner.calls != 2 {
		t.Errorf("calls = %d: a signature may have been added since", inner.calls)
	}
}

// A block under a user rule must not outlast the network coming back.
func TestAFailureIsNeverStored(t *testing.T) {
	inner, v, _ := cachedAt(t, Failed)
	ctx := context.Background()
	_, _ = v.Verify(ctx, candidate, cacheRule)
	_, _ = v.Verify(ctx, candidate, cacheRule)
	if inner.calls != 2 {
		t.Errorf("calls = %d, want every failure asked again", inner.calls)
	}
}

func TestEditingTheRuleMissesTheCache(t *testing.T) {
	inner, v, _ := cachedAt(t, Verified)
	ctx := context.Background()
	_, _ = v.Verify(ctx, candidate, cacheRule)
	other := cacheRule
	other.Subject = "someone-else"
	_, _ = v.Verify(ctx, candidate, other)
	if inner.calls != 2 {
		t.Errorf("calls = %d: a verdict answered one identity, not another", inner.calls)
	}
	// Moving the rule or renaming its file is not editing what it asks.
	moved := cacheRule
	moved.Origin, moved.Match = "elsewhere:9", "x/*"
	_, _ = v.Verify(ctx, candidate, moved)
	if inner.calls != 2 {
		t.Errorf("calls = %d: the origin is not part of the question", inner.calls)
	}
}

func TestTheStoreSurvivesARestart(t *testing.T) {
	path := filepath.Join(t.TempDir(), "signature-verdicts.json")
	at := time.Date(2026, 9, 25, 12, 0, 0, 0, time.UTC)
	if err := (FileStore{Path: path}).Set("k", IdentityMismatch, at); err != nil {
		t.Fatal(err)
	}
	v, got, ok := FileStore{Path: path}.Get("k")
	if !ok || v != IdentityMismatch || !got.Equal(at) {
		t.Errorf("Get = %v, %v, %v", v, got, ok)
	}
}

