package scan

import "github.com/anthnel/devdesk/internal/config"

// OptionsFromConfig builds the scan options a context is configured with.
//
// This is the only way ScanOptions is assembled. Three call sites used to do it
// by hand — the security form, the workspaces list and the images list — and
// they had drifted: only the form set IgnoreEOL, so the option applied when
// scanning from the form and silently did not from either list (D26).
//
// OnProgress is deliberately left nil: it is per-scan wiring, not configuration,
// and belongs to whoever starts the scan. So is LoadForgeToken, which needs the
// context's secret store — the caller has it, this function does not.
//
// It takes the whole Config rather than its Scan section because the CI stage
// needs the forge: which platform a context targets is what decides whether a
// repository is graded at all (§3.42), and that is not a scan setting.
func OptionsFromConfig(cfg *config.Config) ScanOptions {
	c := cfg.Scan
	// The address is kept in the config even when the checkbox is off, so
	// switching it back on does not lose what was typed — but a scan must not
	// see it until the checkbox says client-server mode is wanted.
	trivyServer := ""
	if c.Tools.Trivy.Server.Enabled {
		trivyServer = c.Tools.Trivy.Server.URL
	}
	return ScanOptions{
		Categories:  c.Categories,
		Tools:       c.Tools,
		TrivyServer: trivyServer,
		Forge:       cfg.Forge,
	}
}

package config

import "slices"

// The scanners and the categories they serve, as the configuration names them.
//
// The table that says which tool serves which category, what each one needs and
// which are ticked by default lives in internal/scan (toolbox.go): it is the one
// source of truth. This file only declares the identifiers the YAML is written
// with, because the configuration cannot import the package that reads it —
// scan imports config, not the other way round. A test in scan checks that the
// two agree.

// Tool identifiers, as they appear under `scan.tools` and in a category's
// `tools` list.
const (
	ToolTrivy       = "trivy"
	ToolGitleaks    = "gitleaks"
	ToolPlumber     = "plumber"
	ToolKubeconform = "kubeconform"
	ToolHelm        = "helm"
	ToolKustomize   = "kustomize"
)

// ToolIDs lists every scanner, in the order the tables use.
func ToolIDs() []string {
	return []string{ToolTrivy, ToolGitleaks, ToolPlumber, ToolKubeconform, ToolHelm, ToolKustomize}
}

// Category identifiers, as they appear under `scan.categories`.
const (
	CategoryVuln      = "vuln"
	CategorySecret    = "secret"
	CategoryMisconfig = "misconfig"
	CategoryLicense   = "license"
	CategoryCI        = "ci"
)

// CategoryIDs lists every category, in the order the tables use.
func CategoryIDs() []string {
	return []string{CategoryVuln, CategorySecret, CategoryMisconfig, CategoryLicense, CategoryCI}
}

// ToolConfig is what every scanner is configured with: where it runs from, and
// what to run.
type KubeconformConfig struct {
	ToolConfig        `yaml:",inline"`
	KubernetesVersion string `yaml:"kubernetes_version"`
}

// ScanTools is every scanner's settings, one block per tool.
type ScanTools struct {
	Trivy       TrivyConfig       `yaml:"trivy"`
	Gitleaks    GitleaksConfig    `yaml:"gitleaks"`
	Plumber     ToolConfig        `yaml:"plumber"`
	Kubeconform KubeconformConfig `yaml:"kubeconform"`
	Helm        ToolConfig        `yaml:"helm"`
	Kustomize   ToolConfig        `yaml:"kustomize"`
}

// Tool returns the settings every scanner shares, by identifier — what lets
// defaults, path expansion and detection loop over the tools instead of
// repeating a block per tool. Nil for an unknown identifier.
func (t *ScanTools) Tool(id string) *ToolConfig {
	switch id {
	case ToolTrivy:
		return &t.Trivy.ToolConfig
	case ToolGitleaks:
		return &t.Gitleaks.ToolConfig
	case ToolPlumber:
		return &t.Plumber
	case ToolKubeconform:
		return &t.Kubeconform.ToolConfig
	case ToolHelm:
		return &t.Helm
	case ToolKustomize:
		return &t.Kustomize
	}
	return nil
}

// CategoryConfig is one category: whether it runs, and which of its tools run
// it. A category that is off keeps its list, the way the Trivy server keeps its
// address while the mode is off.
type CategoryConfig struct {

// ScanConfig holds the configuration for security scans.
//
// What a scan looks for and what runs it are two questions (§3.86): a category
// is on or off, and each category ticks the tools that serve it. Every tool's
// own settings live under Tools, one block per tool.
type ScanConfig struct {
	Categories ScanCategories `yaml:"categories"`
	Tools      ScanTools      `yaml:"tools"`

	// BaseImageTrack is how far remediation may move a Dockerfile's base image:
	// "same-line" (the default) or "next-major". See base_image_track.go.
	BaseImageTrack string `yaml:"base_image_track"`

	CacheDir           string `yaml:"cache_dir"`            // Report cache
	MaxCachedReports   int    `yaml:"max_cached_reports"`   // Max number of reports kept
	Timeout            int    `yaml:"timeout"`              // Timeout in seconds
	MaxConcurrentScans int    `yaml:"max_concurrent_scans"` // Max number of parallel scans

	// Legacy is the flat keys Categories and Tools replaced. Read at load,
	// migrated by migrateScanSection, and empty from then on.
	//
	// Deprecated: use Categories and Tools.
	Legacy legacyScanKeys `yaml:",inline"`
}

// DefaultKubernetesVersion is the release manifests are validated against when
// the context names none: the newest minor but one for which the schemas
// kubeconform downloads exist (checked on 2026-09-22, 1.37.0 being the newest).
// One behind rather than the newest, because a cluster runs a release that has
// been out for a while, and validating against one it does not run would flag
// fields it does not have yet as accepted.
const DefaultKubernetesVersion = "1.36.0"

// StatusConfig holds the configuration for monitoring
type StatusConfig struct {
	if cfg.App.WorkspacesDir == "" {
		cfg.App.WorkspacesDir = filepath.Join(homeDir, "workspaces")
	}
	if cfg.App.IDECommand == "" {
		cfg.App.IDECommand = "code"
	}
	// Left empty, credentials.Select already treats this as "auto"; naming it
	// keeps the setting inside the closed set the configuration view cycles
	// through, so the first arrow press does not jump somewhere arbitrary.
	if cfg.App.SecretBackend == "" {
		cfg.App.SecretBackend = "auto"
	}
	// Same reason: engine.Resolve reads "" as auto, but the configuration view
	// cycles a closed set and a value outside it has nowhere to start from.
	if cfg.App.ContainerEngine == "" {
		cfg.App.ContainerEngine = EngineAuto
	}
	// Written rather than left empty for the reason above: the configuration
	// view cycles a closed set. A value outside it is left alone — remediation
	// reads it as same-line — so a typo in the file is not silently rewritten.
	if cfg.Scan.BaseImageTrack == "" {
		cfg.Scan.BaseImageTrack = BaseImageTrackSameLine
	}
	if cfg.Status.RefreshInterval == 0 {
		cfg.Status.RefreshInterval = 10
	}
	if cfg.Status.Timeout == 0 {
		cfg.Status.Timeout = 5
	}
	if cfg.Forge.Type == "" {
		cfg.Forge.Type = ForgeGitLab
	}
	if cfg.Forge.DefaultVisibility == "" {
		cfg.Forge.DefaultVisibility = "private"
	}
	if cfg.Forge.CloneMethod == "" {
